/* @autogenerated */
import { TestBed, fakeAsync, tick } from '@angular/core/testing';
import { MatDialog } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { of } from 'rxjs';
import { SpanStatusCode } from '@opentelemetry/api';
import { ErrorService, GlobalErrorHandler } from './error.service';
import { Logger } from './logger.service';
import { InstrumentationService } from './instrumentation.service';
import { IdentityService } from '../identity/identity.service';

describe('ErrorService', () => {
  let service: ErrorService;
  let snackBar: jasmine.SpyObj<MatSnackBar>;
  let dialog: jasmine.SpyObj<MatDialog>;
  let mockSpan: any;
  let mockTracer: any;
  let provider: any;
  let logger: jasmine.SpyObj<Logger>;
  let identity: jasmine.SpyObj<IdentityService>;

  beforeEach(() => {
    logger = jasmine.createSpyObj<Logger>('Logger', ['error']);
    identity = jasmine.createSpyObj<IdentityService>('IdentityService', ['login']);
    mockSpan = {
      setStatus: jasmine.createSpy('setStatus'),
      recordException: jasmine.createSpy('recordException'),
      end: jasmine.createSpy('end'),
      spanContext: () => ({ traceId: '0af7651916cd43dd8448eb211c80319c', spanId: 'b7ad6b7169203331', traceFlags: 1 }),
    };
    mockTracer = { startSpan: jasmine.createSpy('startSpan').and.returnValue(mockSpan) };
    snackBar = jasmine.createSpyObj('MatSnackBar', ['open']);
    snackBar.open.and.returnValue({ afterDismissed: () => of({ dismissedByAction: false }) } as any);
    dialog = jasmine.createSpyObj('MatDialog', ['open']);
    dialog.open.and.returnValue({ afterClosed: () => of(undefined) } as any);
    provider = { getTracer: jasmine.createSpy('getTracer').and.returnValue(mockTracer) };

    TestBed.configureTestingModule({
      providers: [
        ErrorService,
        { provide: MatDialog, useValue: dialog },
        { provide: MatSnackBar, useValue: snackBar },
        { provide: Logger, useValue: logger },
        { provide: InstrumentationService, useValue: provider },
        { provide: IdentityService, useValue: identity },
      ],
    });
    service = TestBed.inject(ErrorService);
  });

  afterEach(() => TestBed.resetTestingModule());

  it('notifyError opens a snackbar with the given message', () => {
    service.notifyError('Something went wrong');
    expect(snackBar.open).toHaveBeenCalledWith('Something went wrong', 'OK', { duration: 5000 });
  });

  it('isCanceled returns true when error has a timeout property', () => {
    expect(service.isCanceled({ timeout: 123 })).toBeTrue();
  });

  it('isCanceled returns false when error has no timeout property', () => {
    expect(service.isCanceled({})).toBeFalse();
  });

  it('cancelError removes the timeout property from the error', fakeAsync(() => {
    const error: any = {};
    error.timeout = setTimeout(() => {}, 5000);
    service.cancelError(error);
    tick(5000);
    expect(error.timeout).toBeUndefined();
  }));

  it('initialiceError sets a timeout on the error object', () => {
    const error: any = { hidden: true };
    service.initialiceError(error);
    expect(error.timeout).toBeDefined();
    clearTimeout(error.timeout);
  });

  it('initialiceError opens the dialog after 2 seconds when error is not hidden', fakeAsync(() => {
    const error: any = { hidden: false };
    service.initialiceError(error);
    tick(2000);
    expect(dialog.open).toHaveBeenCalled();
    expect(dialog.open.calls.mostRecent().args[1]).toEqual({ data: { error, login: undefined } });
  }));

  it('initialiceError offers to sign in with the identity of a 401', fakeAsync(() => {
    const error: any = { hidden: false, status: 401, identity: 'main' };
    service.initialiceError(error);
    tick(2000);
    const data = dialog.open.calls.mostRecent().args[1]!.data as any;
    expect(data.error).toBe(error);
    expect(identity.login).not.toHaveBeenCalled();
    data.login();
    expect(identity.login).toHaveBeenCalledWith('main');
  }));

  it('initialiceError does not offer to sign in for a 401 without identity', fakeAsync(() => {
    service.initialiceError({ hidden: false, status: 401 });
    tick(2000);
    expect((dialog.open.calls.mostRecent().args[1]!.data as any).login).toBeUndefined();
  }));

  it('initialiceError shows a snackbar for 422 errors', fakeAsync(() => {
    const error: any = { hidden: false, status: 422 };
    service.initialiceError(error);
    tick(2000);
    expect(snackBar.open).toHaveBeenCalledWith(
      'Ha ocurrido un error, la lista de datos enviados es incorrecta',
      undefined,
      { duration: 2000 },
    );
  }));

  it('initialiceError does not open dialog when error is hidden', fakeAsync(() => {
    const error: any = { hidden: true };
    service.initialiceError(error);
    tick(2000);
    expect(dialog.open).not.toHaveBeenCalled();
  }));

  it('storeError records a span with ERROR status and the error message', () => {
    const error = { message: 'oops' };
    service.storeError(error);

    expect(provider.getTracer).toHaveBeenCalledWith('oops');
    expect(mockTracer.startSpan).toHaveBeenCalledWith('oops');
    expect(mockSpan.setStatus).toHaveBeenCalledWith({ code: SpanStatusCode.ERROR, message: 'oops' });
    expect(mockSpan.recordException).toHaveBeenCalledWith(error);
    expect(mockSpan.end).toHaveBeenCalled();
    expect(logger.error).toHaveBeenCalledWith('Unhandled error', error);
  });

  it('storeError uses a fallback message when error has no message', () => {
    service.storeError({});
    expect(provider.getTracer).toHaveBeenCalledWith('Unspecified error');
  });

  it('storeError annotates the error with the traceId for support', () => {
    const error: any = { message: 'oops' };
    service.storeError(error);
    expect(error.traceId).toBe('0af7651916cd43dd8448eb211c80319c');
  });

  it('storeError does not annotate an invalid (no-op) trace', () => {
    mockSpan.spanContext = () => ({
      traceId: '00000000000000000000000000000000',
      spanId: '0000000000000000',
      traceFlags: 0,
    });
    const error: any = { message: 'oops' };
    service.storeError(error);
    expect(error.traceId).toBeUndefined();
  });
});

describe('GlobalErrorHandler', () => {
  it('delegates to ErrorService.storeError via the injector', () => {
    const storeError = jasmine.createSpy('storeError');
    const injector = { get: jasmine.createSpy('get').and.returnValue({ storeError }) };
    const handler = new GlobalErrorHandler(injector as any);

    handler.handleError({ message: 'boom' });

    expect(storeError).toHaveBeenCalledWith({ message: 'boom' });
  });
});
